package dev.smpcristalix.pvpcombat.service;
import dev.smpcristalix.pvpcombat.config.PvPCombatSettings;import dev.smpcristalix.pvpcombat.data.*;import org.bukkit.attribute.Attribute;import org.bukkit.entity.Player;import java.util.UUID;
/** Преобразует дискретные ступени игрока в реальные игровые характеристики. */
public final class StatsService{private final YamlDataStore store;private PvPCombatSettings settings;public StatsService(YamlDataStore s,PvPCombatSettings c){store=s;settings=c;}public void reload(PvPCombatSettings c){settings=c;}public PlayerProfile profile(UUID u){return store.profile(u);}public void clamp(PlayerProfile p){p.damageLevel(clamp(p.damageLevel(),0,settings.damageLevels()));p.speedLevel(clamp(p.speedLevel(),0,settings.speedLevels()));p.satietyLevel(clamp(p.satietyLevel(),0,settings.satietyLevels()));p.abilityLevel(clamp(p.abilityLevel(),0,settings.maxAbilityLevel()));p.healthStep(clamp(p.healthStep(),minHealthStep(),maxHealthStep()));}public void apply(Player player){PlayerProfile p=profile(player.getUniqueId());clamp(p);var health=player.getAttribute(Attribute.GENERIC_MAX_HEALTH);if(health!=null)health.setBaseValue(healthHearts(p)*2.0);if(player.getHealth()>player.getMaxHealth())player.setHealth(player.getMaxHealth());var speed=player.getAttribute(Attribute.GENERIC_MOVEMENT_SPEED);if(speed!=null)speed.setBaseValue(0.1*(1.0+speedBonusPercent(p)/100.0));}public double damageBonusPercent(PlayerProfile p){return settings.maxDamagePercent()*p.damageLevel()/settings.damageLevels();}public double speedBonusPercent(PlayerProfile p){return settings.maxSpeedPercent()*p.speedLevel()/settings.speedLevels();}public double satietyReductionPercent(PlayerProfile p){return settings.maxSatietyReductionPercent()*p.satietyLevel()/settings.satietyLevels();}public double healthHearts(PlayerProfile p){return settings.baseHealthHearts()+p.healthStep()*settings.healthHeartsPerStep();}public int minHealthStep(){return(int)Math.round((settings.minHealthHearts()-settings.baseHealthHearts())/settings.healthHeartsPerStep());}public int maxHealthStep(){return(int)Math.round((settings.maxHealthHearts()-settings.baseHealthHearts())/settings.healthHeartsPerStep());}private static int clamp(int v,int min,int max){return Math.max(min,Math.min(max,v));}}
